export const DEFAULT_CALIBRATION={closed:0,open:1,left:-45,right:45};
const clamp=(v,lo=0,hi=1)=>Math.max(lo,Math.min(hi,v));
export function angle(a,b,c){const u=[a.x-b.x,a.y-b.y,(a.z||0)-(b.z||0)],v=[c.x-b.x,c.y-b.y,(c.z||0)-(b.z||0)],den=Math.hypot(...u)*Math.hypot(...v);if(den<1e-10)return null;return Math.acos(clamp(u.reduce((s,x,i)=>s+x*v[i],0)/den,-1,1))*180/Math.PI}
export function handFeatures(landmarks,world,width=640,height=480){if(!landmarks||landmarks.length!==21)return null;const points=world?.length===21?world:landmarks.map(p=>({x:p.x*width,y:p.y*height,z:(p.z||0)*width}));const bends=[[5,6,7],[9,10,11],[13,14,15],[17,18,19]].map(([a,b,c])=>angle(points[a],points[b],points[c]));if(bends.some(v=>v===null||!Number.isFinite(v)))return null;const openness=bends.reduce((s,v)=>s+clamp((v-50)/125),0)/4;const wrist=landmarks[0],middle=landmarks[9],dx=-(middle.x-wrist.x)*width,dy=(wrist.y-middle.y)*height;if(Math.hypot(dx,dy)<height*.015)return null;const roll=Math.atan2(dx,dy)*180/Math.PI;return Number.isFinite(roll)?{openness,roll}:null}
export function normalizeFeatures(raw,cal=DEFAULT_CALIBRATION){return{x:clamp((raw.openness-cal.closed)/Math.max(.15,cal.open-cal.closed)),y:1-clamp((raw.roll-cal.left)/Math.max(20,cal.right-cal.left))}}
export function calibrated(cal,key,value){const next={...cal,[key]:value};if((key==='closed'||key==='open')&&next.open-next.closed<.15)throw new Error('Open and closed poses are too similar. Open your fingers farther, or close them more.');if((key==='left'||key==='right')&&next.right-next.left<20)throw new Error('Tilt endpoints are too close or reversed. Keep fingers up and tilt toward the indicated side.');return next}
export class GestureSmoother{constructor(){this.position=null;this.last=null}update(target,time){if(!this.position){this.position={...target};this.last=time;return{...target}}const dt=clamp((time-this.last)/1000,.001,.12);this.last=time;const alpha=1-Math.exp(-dt/.09);let dx=(target.x-this.position.x)*alpha,dy=(target.y-this.position.y)*alpha;const dist=Math.hypot(dx,dy),limit=2.5*dt;if(dist>limit){dx*=limit/dist;dy*=limit/dist}this.position.x=clamp(this.position.x+dx);this.position.y=clamp(this.position.y+dy);return{...this.position}}reset(){this.position=null;this.last=null}}
